"""Calculate a z-score given a value, mean, and standard deviation.

    NOTE: The z_score() of a constant vector is 0
    """
def z_score(val: Any, v_mean: Any, v_std: Any) -> object {
    score = 0 if (v_std == 0) else ((val - v_mean) / v_std);
    return score;
}

